insert into public.policies
  (id, titulo, ciudad, pais, categoria, anio, resumen, resultados, fuente_nombre, fuente_url, evidencia_nivel, evidencia_nota)
values
  ('seed-1', 'Superilles (supermanzanas)', 'Barcelona', 'España', 'movilidad', '2016', 'Reorganiza el tráfico en ''supermanzanas'' de varias cuadras para devolver a peatones y vecinos el espacio antes ocupado por autos, creando ejes verdes y plazas en los cruces.', 'Reducción medida de tráfico privado y de contaminación acústica en las zonas piloto (Poblenou, Sant Antoni, Horta), más espacio comunitario y comercio de cercanía.', 'Ajuntament de Barcelona / C40 Cities', 'https://ajuntament.barcelona.cat/superilles/en', 'media', 'Cifra difundida por el propio ayuntamiento y por la red C40; no se cita una evaluacion academica independiente.'),
  ('seed-2', 'Red Integrada de Transporte (RIT) — primer BRT del mundo', 'Curitiba', 'Brasil', 'movilidad', '1974', 'Sistema de buses troncal-alimentador con carriles exclusivos y estaciones tubulares de embarque a nivel, integrado con la planificación del uso del suelo.', 'En su pico (2014) transportaba cerca de 2,3-2,5 millones de pasajeros por día entre Curitiba y 13 municipios metropolitanos, a una fracción del costo de un metro.', 'C40 Cities / ITDP', 'https://www.c40.org/case-studies/c40-good-practice-guides-curitiba-bus-rapid-transit-modernisation/', 'alta', 'Caso estudiado durante decadas por especialistas en transporte (ITDP, C40) como referencia mundial de BRT.'),
  ('seed-3', 'Programa de Agricultura Urbana (PAU)', 'Rosario', 'Argentina', 'ambiente', '2002', 'Nacido en la crisis de 2001, convirtió terrenos baldíos, basurales y bordes de vías en parques huerta agroecológicos gestionados por vecinos y vecinas.', 'Hoy suma unas 30-40 hectáreas entre parques huerta y cinturón verde, cientos de huerteras y huerteros (60% mujeres) y miles de toneladas anuales de alimentos; reconocido internacionalmente (premio del WRI Ross Center, 2021).', 'Infobae / CIPDH / La tinta', 'https://www.infobae.com/america/soluciones/2022/11/16/el-programa-de-agricultura-urbana-de-rosario-produce-alimentos-agroecologicos-y-da-trabajo-a-360-personas/', 'media', 'Cifras de superficie y empleo difundidas por el propio municipio y retomadas por prensa; el premio de 2021 reconoce la experiencia pero no mide impacto nutricional o economico con metodologia propia.'),
  ('seed-4', 'Metrocable', 'Medellín', 'Colombia', 'inclusion', '2004', 'Teleférico urbano integrado al sistema de metro que conecta comunas populares construidas en laderas, antes aisladas, con el resto de la ciudad.', 'El viaje al centro desde Santo Domingo bajó de hasta dos horas en bus a siete minutos; la actividad comercial alrededor de las estaciones creció un 40% y se evitan unas 20.000 toneladas de CO2 al año.', 'ONU-Hábitat', 'https://onu-habitat.org/index.php/metrocable-medellin-estudio-de-caso', 'media', 'Estudio de caso de ONU-Habitat, un organismo multilateral, pero basado en su mayor parte en datos aportados por la propia ciudad.'),
  ('seed-5', 'Red de autopistas de bicicleta', 'Copenhague', 'Dinamarca', 'movilidad', '1970s–hoy', 'Infraestructura ciclista continua, segregada y priorizada en semáforos, construida de forma sostenida durante décadas como columna vertebral de la movilidad diaria.', 'El uso de la bicicleta llegó a representar cerca del 45% de los viajes al trabajo o estudio en la ciudad, sobre una red de cientos de kilómetros de ciclovías segregadas.', 'C40 Cities', 'https://www.c40.org/case-studies/c40-good-practice-guides-copenhagen-city-of-cyclists/', 'media', 'Cifra de reparto modal difundida por la red C40 y el propio municipio de Copenhague.'),
  ('seed-6', 'Vivienda social municipal (Gemeindebau)', 'Viena', 'Austria', 'vivienda', '1920s–hoy', 'Parque extenso de vivienda pública de alquiler regulado, construido y gestionado por el municipio desde hace un siglo, abierto a distintos niveles de ingreso.', 'Alrededor de la mitad de la población vienesa vive en departamentos municipales o subsidiados; el municipio es propietario directo de más de 220.000 unidades.', 'Ciudad de Viena (socialhousing.wien)', 'https://socialhousing.wien/', 'alta', 'El porcentaje de vivienda publica surge de registros administrativos de la ciudad, un dato objetivo y verificable, no de una evaluacion de impacto.'),
  ('seed-7', 'Barrio Vauban', 'Friburgo', 'Alemania', 'vivienda', '1990s–2006', 'Barrio diseñado con participación vecinal, prioridad peatonal y ciclista por sobre el auto privado, y estándares altos de eficiencia energética y energía solar.', 'Treinta años después, el 70% de sus habitantes no tiene auto propio y la gran mayoría se moviliza a pie, en bici o en tranvía.', 'Ciudad de Friburgo', 'https://www.freiburg.de/pb/site/Freiburg/get/params_E1152300345/647926/Infotafeln_Vauban_sp.pdf', 'media', 'Cifra de uso del auto basada en encuestas del propio municipio, sin auditoria externa conocida.'),
  ('seed-8', 'Restauración del arroyo Cheonggyecheon', 'Seúl', 'Corea del Sur', 'ambiente', '2005', 'Demolición de una autopista elevada en el centro y recuperación de un curso de agua urbano como parque lineal peatonal.', 'La temperatura del área bajó entre 8% y 18% respecto al resto de la ciudad, se redujo de forma significativa la contaminación por partículas y el corredor recibe unas 64.000 visitas diarias.', 'Seoul Solution (plataforma oficial de la ciudad)', 'https://www.seoulsolution.kr/en/content/seoul-urban-regeneration-cheonggyecheon-restoration-and-downtown-revitalization', 'alta', 'Efecto de temperatura documentado por estudios de microclima citados en plataformas academicas y de la propia ciudad (Seoul Solution).'),
  ('seed-9', 'Housing First', 'Helsinki', 'Finlandia', 'inclusion', '2008', 'Política que entrega vivienda estable a personas en situación de calle sin condiciones previas, combinada con acompañamiento social y sanitario.', 'Entre 2008 y 2022 el sinhogarismo de largo plazo en Finlandia cayó un 68%; en Helsinki las camas de albergue de emergencia bajaron de más de 2.100 a apenas 52.', 'Y-Foundation / Centre for Public Impact', 'https://centreforpublicimpact.org/public-impact-fundamentals/eradicating-homelessness-in-finland-the-housing-first-programme/', 'alta', 'Uno de los casos de politica social mejor documentados: estadisticas nacionales de Finlandia y organismos independientes (OCDE, Centre for Public Impact) coinciden en la tendencia.'),
  ('seed-10', 'Peatonalización del centro histórico', 'Liubliana', 'Eslovenia', 'ambiente', '2007', 'Transformación progresiva del casco céntrico en una zona libre de autos particulares, con transporte eléctrico interno y rediseño del espacio público.', 'El centro ganó más de 12 hectáreas de espacio peatonal y ciclista, con una caída de hasta 70% en contaminación local y unos 6 dB menos de ruido.', 'Ciudad de Liubliana', 'https://www.ljubljana.si/en/ljubljana-for-you/transport-in-ljubljana/transport-around-the-pedestrian-zone-of-the-old-town/', 'media', 'Cifras de superficie peatonal y contaminacion difundidas por el propio municipio de Liubliana.'),
  ('seed-11', 'Piazze Aperte', 'Milán', 'Italia', 'movilidad', '2018', 'Transformación rápida y de bajo costo de cruces e intersecciones ocupadas por tráfico en plazas peatonales, usando pintura, macetas y mobiliario urbano temporal.', 'Entre 2018 y 2022 se realizaron 38 intervenciones (más de 50 a la fecha), con unos 25.000 m² de espacio peatonal nuevo; la mitad de los milaneses vive a 15 minutos de una de estas plazas.', 'Comune di Milano', 'https://www.comune.milano.it/argomenti/partecipazione-civica/piazze-aperte', 'media', 'El municipio de Milan reporta el numero de intervenciones; no se cita una medicion independiente de sus efectos en trafico o comercio.'),
  ('seed-12', 'Pueblo Basura Cero', 'Kamikatsu', 'Japón', 'residuos', '2003', 'Separación de residuos domiciliarios en 45 categorías, con meta declarada de cero relleno sanitario y fuerte involucramiento vecinal.', 'Alcanzó una tasa de reciclaje del 80-81%, muy por encima del promedio japonés (20%), aunque el volumen total de residuos generado no bajó en la última década.', 'Nippon.com', 'https://www.nippon.com/en/guide-to-japan/gu900257/', 'media', 'La tasa de reciclaje es un dato de gestion municipal ampliamente citado por prensa especializada; el propio pueblo reconoce que el volumen total de residuos no bajo.'),
  ('seed-13', 'Transporte público gratuito para residentes', 'Tallin', 'Estonia', 'movilidad', '2013', 'Gratuidad del transporte público urbano para todos los residentes empadronados en la ciudad, financiada con el presupuesto municipal.', 'El uso del transporte público aumentó de forma moderada (cerca de 14% el primer año) y miles de personas se empadronaron como residentes por el beneficio; estudios posteriores muestran un efecto menor al esperado sobre el reparto modal frente al auto.', 'Red Metropolis / ScienceDirect', 'https://use.metropolis.org/case-studies/free-public-transport-in-tallinn', 'alta', 'Caso muy estudiado academicamente (varios papers en revistas de transporte) precisamente porque el efecto fue menor al esperado: un buen ejemplo de evidencia rigurosa con resultado modesto.'),
  ('seed-14', 'Ciclovía dominical', 'Bogotá', 'Colombia', 'salud', '1974–hoy', 'Cierre semanal de avenidas principales al tráfico motorizado para uso recreativo, deportivo y comunitario de la vía pública.', 'Hoy convoca a más de 1,5 millones de personas cada domingo y festivo sobre unos 127 km de vías cerradas al tráfico motorizado; el modelo se replicó en decenas de ciudades del mundo.', 'Alcaldía de Bogotá / IDRD', 'https://bogota.gov.co/mi-ciudad/cultura-recreacion-y-deporte/conoce-mapa-de-rutas-y-los-horarios-de-la-ciclovia-de-bogota-de-2025', 'media', 'Cifra de asistencia dominical difundida por la propia Alcaldia de Bogota; existen estudios de salud publica sobre la Ciclovia, pero no se cita aqui uno con metodologia propia verificada.'),
  ('seed-15', 'Peatonalización total del casco histórico', 'Pontevedra', 'España', 'movilidad', '1999', 'Ciudad de unos 85.000 habitantes (tamaño similar al de muchas ciudades intermedias) que peatonalizó por completo su centro histórico y calmó el tráfico en el resto de la trama urbana desde el primer mes de gestión.', 'De los cerca de 80.000 vehículos que circulaban a diario por el centro en 1999 se pasó a unos 7.000; hoy tiene algunos de los mejores indicadores de España en seguridad vial, calidad del aire y ruido urbano.', 'Concello de Pontevedra', 'https://ok.pontevedra.gal/es/movilidad-alternativa/', 'alta', 'Conteo de trafico antes/despues realizado por el propio Concello, pero replicado y corroborado por observatorios de movilidad europeos y numerosos estudios urbanos independientes durante 25 anios.'),
  ('seed-16', 'Presupuesto Participativo', 'Porto Alegre', 'Brasil', 'gobierno', '1989', 'Primera experiencia mundial de presupuesto participativo: asambleas vecinales deciden junto al municipio buena parte de la inversión pública anual, barrio por barrio.', 'Llegó a ser conocido por el 60% de la población según encuestas de opinión y el modelo fue adoptado luego por más de 70 ciudades brasileñas y cientos en el mundo.', 'ONU-Hábitat / Universidad Politécnica de Madrid', 'https://habitat.aq.upm.es/dubai/96/bp049.html', 'alta', 'Es el caso de presupuesto participativo mas estudiado academicamente en el mundo (cientos de papers), con su adopcion por otras ciudades verificada de forma independiente.'),
  ('seed-17', 'Cultura ciudadana', 'Bogotá', 'Colombia', 'seguridad', '1995', 'Bajo la alcaldía de Antanas Mockus, combinó pedagogía cívica (mimos de tránsito, tarjetas ciudadanas, la ''ley zanahoria'' de restricción horaria al alcohol) con gestión policial para cambiar comportamientos de riesgo.', 'La tasa de homicidios bajó de un promedio anual de 55 a 25 por cada 100.000 habitantes y las muertes por accidentes de tránsito de 24 a 7 por cada 100.000 durante sus dos mandatos; especialistas debaten cuánto de esa caída responde a la cultura ciudadana y cuánto a otros factores nacionales de la época.', 'El Tiempo', 'https://www.eltiempo.com/archivo/documento/CMS-12225158', 'media', 'Las cifras de homicidios y siniestros viales son oficiales, pero especialistas citados por El Tiempo debaten cuanto responde a la politica y cuanto a otros factores nacionales de la epoca.'),
  ('seed-18', 'Preston Model (community wealth building)', 'Preston', 'Reino Unido', 'economia', '2013', 'Ante el colapso de una gran inversión privada, el municipio rediseñó las compras públicas para que instituciones ancla (universidad, colegios, policía) gastaran más en proveedores locales y cooperativas.', 'El gasto retenido en la economía local subió del 5% al 18,2% en cinco años y el desempleo cayó de 8,8% (2012) a 3,4% (2020); Preston fue nombrada ''ciudad más mejorada del Reino Unido'' en 2018.', 'CLES (Centre for Local Economic Strategies)', 'https://cles.org.uk/community-wealth-building-in-practice/community-wealth-building-places/community-wealth-building-in-preston/', 'media', 'La evaluacion fue realizada por CLES, la misma organizacion que aseso el diseno de la politica: no es una fuente independiente del programa que evalua.'),
  ('seed-19', 'Parques Biblioteca', 'Medellín', 'Colombia', 'educacion', '2006', 'Bibliotecas públicas de diseño arquitectónico destacado construidas en las laderas más pobres y golpeadas por la violencia, combinadas con espacio público y programación cultural.', 'Se convirtieron en referencia de ''urbanismo social'' y catalizadores de la revitalización de barrios como Santo Domingo, aunque estudios académicos matizan su impacto real más allá del efecto simbólico y turístico.', 'BID (Banco Interamericano de Desarrollo)', 'https://blogs.iadb.org/ciudades-sostenibles/es/la-inversion-social-en-los-parques-biblioteca-de-medellin/', 'media', 'El BID documenta la inversion y su narrativa, pero el propio articulo cita estudios academicos que matizan el impacto real mas alla de lo simbolico.'),
  ('seed-20', 'Programa de Peso Saludable', 'Ámsterdam', 'Países Bajos', 'salud', '2012', 'Estrategia municipal de largo plazo que interviene sobre alimentación, actividad física y sueño infantil desde la escuela, el barrio y el sistema de salud.', 'El sobrepeso y la obesidad infantil bajaron de 21% (2012) a 18,7% (2017), con la mejora más marcada entre niños y niñas de barrios de menores ingresos.', 'PubMed / European Journal of Public Health', 'https://pubmed.ncbi.nlm.nih.gov/34631137/', 'alta', 'Estudio publicado en una revista cientifica con revision por pares (European Journal of Public Health), con medicion antes/despues en la poblacion infantil.'),
  ('seed-21', 'Vivienda pública HDB', 'Singapur', 'Singapur', 'vivienda', '1960', 'Un organismo estatal (HDB) construye y financia vivienda en propiedad para la gran mayoría de la población, integrando barrios por origen étnico y nivel de ingreso.', 'Cerca del 77-80% de los residentes vive en vivienda HDB y alrededor del 90% de esos hogares es propietario de su vivienda.', 'National Library Board de Singapur', 'https://www.nlb.gov.sg/main/article-detail?cmsuuid=3abd40aa-0d91-4352-b9fe-0de1d68e3d85', 'alta', 'Porcentaje de vivienda publica y de propiedad basado en estadisticas oficiales de vivienda de Singapur, un dato demografico objetivo.'),
  ('seed-22', 'Câmbio Verde', 'Curitiba', 'Brasil', 'residuos', '1991', 'Programa municipal que permite canjear residuos reciclables y aceite de cocina usado por frutas y verduras frescas de productores locales, en puntos de encuentro barriales.', 'En 2024 recolectó cerca de 2.500 toneladas de reciclables y entregó 738 toneladas de alimentos a más de 54.000 familias.', 'Prefeitura de Curitiba', 'https://www.curitiba.pr.gov.br/noticias/populacao-de-curitiba-pode-trocar-material-reciclado-por-alimentos-saudaveis-no-cambio-verde/75746', 'media', 'Cifras de toneladas canjeadas difundidas por la propia Prefeitura de Curitiba, sin auditoria externa citada.'),
  ('seed-23', 'Escaleras eléctricas de la Comuna 13', 'Medellín', 'Colombia', 'inclusion', '2011', 'Escaleras mecánicas públicas y gratuitas que reemplazaron 350 escalones empinados en un barrio históricamente golpeado por la violencia, integradas a un proyecto urbano integral.', 'Benefician directamente a más de 12.000 residentes y el sector pasó a recibir hasta 10.000-15.000 visitantes por día, generando turismo y comercio local.', 'Alcaldía de Medellín', 'https://www.medellin.gov.co/es/sala-de-prensa/noticias/las-escaleras-electricas-de-la-comuna-13-en-medellin-una-transformacion-urbana-que-cambio-vidas/', 'baja', 'La cifra de visitantes diarios es una estimacion oficial de tono promocional; no se cita un conteo independiente ni una medicion de impacto economico.'),
  ('seed-24', 'Umuganda (jornada comunitaria de trabajo)', 'Kigali', 'Ruanda', 'ambiente', '2009', 'El último sábado de cada mes, toda la comunidad dedica una mañana a tareas colectivas: limpieza de calles, forestación, mantenimiento de espacios públicos y pequeñas obras.', 'Kigali es reconocida como una de las ciudades más limpias de África; entre 2007 y 2016 el valor económico de las obras realizadas se estimó en unos 127 millones de dólares. Es un modelo de participación obligatoria (con multa por inasistencia), distinto de las jornadas voluntarias más comunes en otros países.', 'Rwanda Governance Board / NPR', 'https://www.npr.org/sections/goatsandsoda/2018/07/18/628364015/how-rwanda-tidied-up-its-streets-and-the-rest-of-the-country-too', 'media', 'El valor economico de las obras es una estimacion del propio gobierno de Ruanda; la cobertura de NPR es periodismo independiente pero no una auditoria de esa cifra.'),
  ('seed-25', 'Presupuesto Participativo', 'Rosario', 'Argentina', 'gobierno', '2002', 'Primera experiencia de presupuesto participativo del país: asambleas barriales debaten y deciden junto al municipio una parte de la inversión pública de cada distrito.', 'Se sostiene sin interrupciones desde 2002 y en 2023/24 recibió una mención especial del Observatorio Internacional de la Democracia Participativa (OIDP) por su reconversión post-pandemia.', 'Rosario Noticias (Municipalidad de Rosario)', 'https://www.rosarionoticias.gob.ar/page/noticias/id/457231/title/Rosario-recibi%C3%B3-un-premio-internacional-por-la-experiencia-del-Presupuesto-Participativo', 'media', 'El sostenimiento del programa y la mencion del OIDP estan documentados, pero las cifras de participacion provienen del propio municipio.'),
  ('seed-26', 'Metrobus', 'Buenos Aires', 'Argentina', 'movilidad', '2011', 'Red de corredores con carriles exclusivos y estaciones techadas para colectivos, construida sobre las avenidas más congestionadas de la ciudad.', 'Según el Gobierno porteño, la red reduce entre 20% y 50% el tiempo de viaje según el corredor y en 2019 ya beneficiaba a más del 20% de los pasajeros de colectivo de la ciudad; especialistas en transporte matizan cuánto de esa reducción se debe a menos paradas y no solo a los carriles exclusivos.', 'Gobierno de la Ciudad de Buenos Aires', 'https://buenosaires.gob.ar/noticias/mas-del-20-de-los-pasajeros-de-la-ciudad-ya-disfrutan-del-metrobus', 'media', 'Las reducciones de tiempo de viaje son datos oficiales del Gobierno porteno; la critica especializada senala que buena parte de la mejora se debe a tener menos paradas, no solo al carril exclusivo.'),
  ('seed-27', 'Ecobici', 'Buenos Aires', 'Argentina', 'movilidad', '2010', 'Primer sistema de bicicletas públicas del país, integrado a una red creciente de ciclovías protegidas.', 'Cuenta con unas 400 estaciones en casi todos los barrios porteños y más de 1,1 millón de usuarios registrados; en 2024 los viajes crecían a un ritmo cercano al 20% interanual, con más de 8.000 viajes diarios en promedio.', 'LA NACION / Infobae', 'https://www.infobae.com/tendencias/2024/05/21/movilidad-sustentable-como-es-el-renovado-sistema-de-ecobici-en-la-ciudad-de-buenos-aires/', 'media', 'Cifras de usuarios y viajes difundidas por el operador del sistema y retomadas por medios; no hay auditoria independiente citada.'),
  ('seed-28', 'Ley de Basura Cero', 'Buenos Aires', 'Argentina', 'residuos', '2005', 'Marco legal pionero en el país que fija metas progresivas de reducción de residuos enviados a relleno sanitario y prohíbe la incineración.', 'Estableció una hoja de ruta clara (30% menos para 2010, 50% para 2012, 75% para 2017), pero según Greenpeace y otros informes la Ciudad no cumplió ninguna de esas metas y debió correr los plazos varias veces; es un caso útil para pensar qué hace falta además de la norma para que una política de residuos funcione.', 'Greenpeace Argentina', 'https://www.greenpeace.org/argentina/participa/involucrate/con-incineracion-no-hay-basura-cero/ley-de-basura-cero-mas-de-14-anos-de-metas-incumplidas/', 'alta', 'Evidencia solida, pero de incumplimiento: Greenpeace y otros informes contrastan las metas legales contra los datos reales de disposicion final durante casi 20 anios.'),
  ('seed-29', 'Centro de Operaciones Tigre (COT)', 'Tigre', 'Argentina', 'seguridad', '2010', 'Centro municipal que integra más de 2.300 cámaras de videovigilancia, patrullaje propio y una app de alerta vecinal en un único sistema de monitoreo permanente.', 'Según datos oficiales de 2025, la tasa de homicidios en ocasión de robo llegó a 0% y más de 150.000 vecinos usan la app Alerta Tigre Global; son cifras difundidas por el propio municipio, sin una auditoría externa independiente que citemos aquí.', 'Municipio de Tigre', 'https://www.tigre.gob.ar/seguridad/cot', 'baja', 'Las cifras (0% de homicidios en ocasion de robo, etc.) provienen exclusivamente de comunicados del propio municipio; no se cita ninguna fuente externa que las corrobore.'),
  ('seed-30', 'Examen Local Voluntario de los ODS', 'Villa María', 'Argentina', 'gobierno', '2022', 'Una de las pocas ciudades argentinas de tamaño intermedio en presentar ante Naciones Unidas un informe propio sobre su avance hacia los Objetivos de Desarrollo Sostenible, articulando gestión municipal, sector privado y organizaciones sociales.', 'El propio municipio documenta programas sostenidos de participación ciudadana (presupuesto participativo, juntas y consejos vecinales) como parte de esa estrategia hacia la Agenda 2030.', 'ONU / Municipalidad de Villa María', 'https://sdgs.un.org/sites/default/files/vlrs/2022-12/municipio_de_villa_maria.pdf', 'media', 'Es un informe que el propio municipio presenta ante la ONU; el mecanismo de Examen Local Voluntario es reconocido internacionalmente, pero su contenido no es auditado por un tercero.'),
  ('seed-31', 'Modelo de desarrollo económico local (ICEDeL)', 'Rafaela', 'Argentina', 'economia', '1996', 'Instituto municipal de capacitación y estudios para el desarrollo local que articula PyMEs, sindicatos, universidades y el Estado en una estrategia de desarrollo territorial de largo plazo; la CEPAL estudió el caso como referencia de ''entorno institucional'' favorable a la competitividad de las pequeñas empresas.', 'Sostenido de forma ininterrumpida desde 1996, generó un centro de capacitación de dirigentes con cientos de egresados y un sistema propio de indicadores socioeconómicos locales que sigue actualizándose año a año.', 'ICEDeL / Municipalidad de Rafaela', 'https://icedel.rafaela.gob.ar/archivos/ORDICEdel/ICEDEL_RelevamientoSocioEconomico_2024.pdf', 'alta', 'Estudiado academicamente por economistas y por la CEPAL, un organismo de investigacion independiente del municipio.'),
  ('seed-32', 'Plan Director de Arbolado y Censo Ciudadano de Árboles', 'Bahía Blanca', 'Argentina', 'ambiente', '2019', 'Plan de 20 años para renovar el arbolado urbano por especies más sanas y adaptadas, apoyado en una app de gobierno abierto donde cualquier vecino puede relevar y georreferenciar árboles de la ciudad.', 'El propio relevamiento municipal detectó más de 1.200 árboles caídos y 300 en riesgo, el diagnóstico que dio origen al plan; es un caso más de planificación de largo plazo que de resultado ya alcanzado.', 'Municipio de Bahía Blanca', 'https://www.bahia.gob.ar/arbolado/censo/', 'sin-evaluacion', 'Es un plan a 20 anios recien puesto en marcha: el propio relevamiento municipal que le dio origen es el unico dato disponible, todavia no hay resultados de impacto.'),
  ('seed-33', 'Presupuesto Participativo Barrial', 'Córdoba', 'Argentina', 'gobierno', '2020', 'Proceso voluntario y universal en el que los vecinos deciden en talleres, por Centro de Participación Comunal, en qué obras de infraestructura barrial invertir una parte del presupuesto municipal.', 'En su tercera edición (2022) el presupuesto asignado creció un 20% respecto del año anterior, unos $459 millones distribuidos según un Índice de Prioridad Social entre 100 barrios de la ciudad.', 'Diario El Puntal (sobre datos de la Municipalidad de Córdoba)', 'https://www.puntalvillamaria.com.ar/presupuesto/aumenta-un-20-el-presupuesto-participativo-barrial-cordoba-n170568', 'media', 'El incremento presupuestario es un dato oficial difundido por la Municipalidad de Cordoba y retomado por un medio de Villa Maria; no hay evaluacion de impacto de las obras financiadas.'),
  ('seed-34', 'Modelo de salud mental comunitaria (fin del manicomio)', 'Trieste', 'Italia', 'bienestar', '1978', 'Tras la Ley Basaglia, Trieste cerró su hospital psiquiátrico y construyó una red de centros de salud mental barriales abiertos las 24 horas, cooperativas de trabajo y vivienda asistida en lugar de internación.', 'Es Centro Colaborador de la OMS en salud mental desde 1987 y la propia OMS lo documenta como modelo de referencia mundial de atención comunitaria, replicado con apoyo técnico en más de 30 países.', 'Estrategia de Desinstitucionalización (Gobierno de España) / OMS', 'https://estrategiadesinstitucionalizacion.gob.es/wp-content/uploads/2023/09/DI_Caso9_Italia-salud-mental.pdf', 'alta', 'Documentado durante más de 40 años por la propia OMS (que lo designó Centro Colaborador) y por decenas de estudios académicos independientes en distintos países.'),
  ('seed-35', 'Modelo islandés de prevención (Planet Youth)', 'Reikiavik', 'Islandia', 'bienestar', '1998', 'Nacido en Reikiavik, combina más horas de familia, deporte y actividades extracurriculares gratuitas con límites horarios nocturnos para adolescentes, coordinados por cada municipio a partir de encuestas escolares anuales.', 'Entre 1998 y 2015 el consumo diario de tabaco en adolescentes de 15-16 años bajó de 23% a cerca de 3%, el consumo de alcohol en el último mes de 42% a 5% y el de cannabis se redujo a la mitad; hoy Islandia tiene de las tasas de consumo adolescente más bajas de Europa.', 'Oficina de Naciones Unidas contra la Droga y el Delito (UNODC)', 'https://www.unodc.org/colombia/es/islandia--ejemplo-global-en-la-prevencion-del-consumo-de-drogas-en-adolescentes.html', 'alta', 'Seguimiento con encuestas estandarizadas (ESPAD) durante más de 20 años y evaluado por investigadores islandeses independientes del gobierno municipal; replicado y estudiado en más de 100 ciudades.'),
  ('seed-36', 'Programa Habilidades para la Vida', 'Santiago', 'Chile', 'bienestar', '1998', 'Programa nacional (ejecutado escuela por escuela) de promoción de salud mental y detección temprana de riesgo psicosocial en niños y adolescentes, coordinado por JUNAEB con equipos psicosociales en cada establecimiento.', 'Un estudio de la Universidad de Chile encontró que entre 2017 y 2020 los estudiantes beneficiarios aumentaron su tasa de promoción de curso un 5,9%, frente a un 2,8% en estudiantes no beneficiarios comparables.', 'Universidad de Chile / JUNAEB', 'https://www.eldinamo.cl/pais/2024/11/27/los-resultados-del-programa-habilidades-para-la-vida-en-el-fomento-de-entornos-escolares-saludables/', 'alta', 'Evaluación cuantitativa con grupo de comparación realizada por una universidad pública, externa a JUNAEB (el organismo que ejecuta el programa).'),
  ('seed-37', 'ThriveNYC', 'Nueva York', 'Estados Unidos', 'bienestar', '2015', 'Programa municipal de gran escala (más de u$s 1.000 millones en varios años) para ampliar el acceso a salud mental mediante decenas de líneas de ayuda, capacitaciones y equipos comunitarios en toda la ciudad.', 'La Contraloría de Nueva York y varios medios documentaron que, años después de lanzado, el programa no podía mostrar con claridad en qué se había gastado el dinero ni si había mejorado indicadores de salud mental de la población; es un caso de alto gasto con evaluación de impacto deficiente.', 'CBS News / Gotham Gazette', 'https://www.cbsnews.com/newyork/news/city-comptroller-to-investigate-thrivenyc-mental-health-initiatives-850-million-efforts', 'baja', 'La propia Contraloría de la ciudad (un organismo de control externo) señaló falta de métricas claras de resultado durante los primeros años del programa; se incluye como ejemplo de qué evitar, no de qué imitar.'),
  ('seed-38', 'Reforma de la red municipal de educación', 'Sobral', 'Brasil', 'educacion', '1997', 'Ciudad mediana del interior de Ceará que rediseñó de punta a punta su red de escuelas municipales: metas claras de alfabetización a los 6 años, formación y seguimiento constante de docentes, y datos de cada escuela puestos a disposición pública.', 'Pasó del puesto 1.366 al 1° lugar de Brasil entre municipios de más de 100.000 habitantes en el índice nacional IDEB, sosteniendo el liderazgo por más de una década; el Banco Mundial publicó un informe tomando el caso como referencia.', 'INEP/MEC (Brasil) — Índice IDEB / Banco Mundial', 'https://www.sobral.ce.gov.br/informes/principais/educacao-de-sobral-supera-anos-anteriores-e-alcanca-melhores-resultados-da-historia-no-ideb-2025', 'alta', 'Medido por una evaluación nacional estandarizada e independiente del municipio (IDEB/INEP), con seguimiento año a año durante casi dos décadas, y documentado por el Banco Mundial.'),
  ('seed-39', 'Pre-K for All (preescolar público universal)', 'Nueva York', 'Estados Unidos', 'educacion', '2014', 'Preescolar gratuito y de jornada completa para todos los niños y niñas de 4 años de la ciudad, con más de 68.000 estudiantes inscriptos en su segundo año, la mitad de familias de bajos ingresos.', 'El Departamento de Educación financió una evaluación independiente con metodología de lotería (comparando ganadores y no ganadores del sorteo de vacantes) para medir el efecto real sobre la preparación escolar; los resultados completos se fueron publicando por etapas.', 'Institute of Education Sciences (Departamento de Educación de EE.UU.)', 'https://ies.ed.gov/use-work/awards/strengthening-school-readiness-through-pre-k-all-university-district-partnership', 'alta', 'Evaluación con diseño de experimento aleatorizado (lotería) financiada por una agencia federal de investigación educativa, independiente de la gestión del programa.'),
  ('seed-40', 'Operation Ceasefire (disuasión focalizada contra la violencia armada)', 'Boston', 'Estados Unidos', 'seguridad', '1996', 'En vez de vigilar barrios enteros, la policía identificó a los grupos concretos responsables de la mayoría de los tiroteos y les advirtió directamente: la violencia tendría consecuencias legales inmediatas y coordinadas, combinado con oportunidades reales de salida (trabajo, estudio).', 'Los homicidios juveniles mensuales bajaron 63% respecto del período previo, con caídas también en asaltos con arma y llamadas al 911; un estudio comparó la tendencia de Boston contra la de otras grandes ciudades de EE.UU. para descartar que fuera solo una baja general del delito.', 'National Institute of Justice / Journal of Research in Crime and Delinquency', 'https://crimesolutions.ojp.gov/ratedprograms/operation-ceasefire-boston-mass', 'alta', 'Evaluado con series de tiempo y un grupo de comparación de otras ciudades por criminólogos externos, publicado en una revista académica con revisión por pares; calificado ''Effective'' por el catálogo federal de evidencia de EE.UU.'),
  ('seed-41', 'Unidad de Reducción de la Violencia (enfoque de salud pública)', 'Glasgow', 'Reino Unido', 'seguridad', '2005', 'Tratando la violencia armada como una epidemia y no solo como un delito, combina policías con médicos, trabajadores sociales y ex pandilleros para intervenir tempranamente sobre jóvenes en riesgo, dentro y fuera de los hospitales.', 'Las lesiones por arma blanca atendidas en hospitales de Glasgow cayeron más de 60% entre 2004 y 2017, y los homicidios en Escocia bajaron a menos de la mitad; el modelo se replicó en Inglaterra y Gales con 20 unidades nuevas.', 'The Irish Times / University of Glasgow', 'https://www.irishtimes.com/news/crime-and-law/would-scotland-s-solution-to-knife-crime-work-in-ireland-1.4676717', 'media', 'Un criminólogo de la Universidad de Glasgow señaló públicamente que existe ''sorprendentemente poca evaluación rigurosa'' del impacto real de la unidad, ya que la violencia también cayó en la misma época en ciudades sin un programa similar.'),
  ('seed-42', 'Efecto Guggenheim (regeneración urbana con ancla cultural)', 'Bilbao', 'España', 'economia', '1997', 'La apertura del Museo Guggenheim fue la pieza más visible de un plan más amplio de reconversión de una ciudad industrial en declive: nuevo metro, saneamiento de la ría, espacio público y conexiones internacionales.', 'Según cálculos del propio museo, aporta 424,6 millones de euros anuales al PIB local y sostiene más de 9.000 empleos; los responsables de la regeneración urbana de Bilbao aclaran que el museo fue ''una parte importante del proceso, pero había muchos otros proyectos ocurriendo al mismo tiempo''.', 'Arquitectura y Diseño / Yale Insights', 'https://www.arquitecturaydiseno.es/arquitectura/efecto-guggenheim-30-anos-despues-por-que-bilbao-cambio-para-siempre_13793', 'media', 'La cifra de impacto en el PIB es una estimación del propio museo, no una medición independiente; los propios gestores de la regeneración de Bilbao advierten que atribuir el éxito solo al edificio es una simplificación.'),
  ('seed-43', 'Reconversión post-industrial (del acero a la tecnología y la salud)', 'Pittsburgh', 'Estados Unidos', 'economia', '1985', 'Tras perder más de 150.000 empleos industriales y buena parte de su población en los años 80, apostó a sus universidades (Carnegie Mellon, Universidad de Pittsburgh) para atraer investigación, robótica, salud avanzada y tecnología.', 'Hoy es referencia mundial en robótica y vehículos autónomos y fue sede de la cumbre del G20 en 2009 como símbolo de reconversión ''verde''; un economista de la Universidad de Pittsburgh que estudió el caso a fondo concluye que la transformación es real pero incompleta, con barrios y trabajadores que quedaron atrás.', 'The Conversation (Universidad de Pittsburgh)', 'https://theconversation.com/pittsburghs-post-steel-economy-is-a-success-and-a-warning-for-other-cities-276814', 'media', 'Un economista académico que dedicó un libro entero al caso concluye que es a la vez ''un éxito y una advertencia'': la ciudad se reinventó, pero buena parte de la región sigue sin recuperarse del todo.'),
  ('seed-44', 'Primera fluoración municipal del agua potable', 'Grand Rapids', 'Estados Unidos', 'salud', '1945', 'Ajustó el nivel de flúor de su red de agua potable a la concentración óptima para prevenir caries, usando a la vecina Muskegon como ciudad de control para poder medir el efecto real del cambio.', 'En 11 años la caries dental entre los escolares de Grand Rapids bajó más del 60%; el CDC de EE.UU. considera la fluoración del agua uno de los diez mayores logros de salud pública del siglo XX.', 'Instituto Nacional del Cáncer (NIH) / Michigan Dental Association', 'https://www.cancer.gov/espanol/cancer/causas-prevencion/riesgo/mitos/hoja-informativa-agua-fluorada', 'alta', 'Diseñado desde el inicio como un estudio comparado con una ciudad de control (Muskegon) y siguió siendo estudiado por investigadores independientes durante décadas.'),
  ('seed-45', 'Prohibición de grasas trans en restaurantes', 'Nueva York', 'Estados Unidos', 'salud', '2006', 'Primera normativa de EE.UU. que obligó a restaurantes, panaderías y vendedores ambulantes a eliminar las grasas trans artificiales de sus comidas, dando un plazo de un año y medio para adaptarse.', 'Un estudio de la Universidad de Yale que comparó condados de Nueva York con y sin la restricción, entre 2002 y 2013, encontró una caída de 6,2% en las internaciones hospitalarias por infarto y ACV en las zonas con la prohibición vigente.', 'JAMA Cardiology (Universidad de Yale)', 'https://es.oliveoiltimes.com/health-news/strokes-heart-attacks-drop-trans-fats-restaurants-banned/56289', 'alta', 'Estudio comparativo publicado en una revista médica con revisión por pares, realizado por investigadores universitarios externos a la ciudad.'),
  ('seed-46', 'Programa Basura Cero (Zero Waste)', 'San Francisco', 'Estados Unidos', 'residuos', '1996', 'Primer programa de compostaje a gran escala de EE.UU. y primera ordenanza que obligó por ley a separar reciclables, orgánicos y basura en tres contenedores, tanto a hogares como a comercios.', 'Alcanzó un 80% de desvío de residuos del relleno sanitario en 2012, el más alto de cualquier ciudad de Norteamérica, frente a apenas 27% en 1990; una nota especializada advierte que gran parte del tonelaje desviado corresponde a escombros de construcción, lo que infla la cifra respecto de lo que separan los hogares.', 'SF Environment (Departamento de Medio Ambiente de San Francisco) / C40', 'https://www.sfenvironment.org/zero-waste-program-history-and-outcomes', 'media', 'La tasa de desvío es un indicador de gestión calculado y difundido por el propio municipio; una nota especializada señala que incluir escombros de construcción en el cálculo exagera el porcentaje real de reciclaje doméstico.'),
  ('seed-47', 'Cooperativas de vivienda por ayuda mutua (FUCVAM)', 'Montevideo', 'Uruguay', 'vivienda', '1970', 'Familias organizadas en cooperativas construyen sus propias viviendas con su propio trabajo los fines de semana, sobre tierra de propiedad colectiva cedida por la Intendencia, sin intermediarios inmobiliarios.', 'Hoy federa a más de 730 cooperativas y 35.000 familias en todo Uruguay; un estudio comparativo de la Universidad de la República encontró mejores resultados habitacionales en este modelo frente a la vivienda social tradicional.', 'Universidad de la República (UDELAR) / FUCVAM', 'https://es.wikipedia.org/wiki/Federaci%C3%B3n_Uruguaya_de_Cooperativas_de_Vivienda_por_Ayuda_Mutua', 'alta', 'Comparado académicamente contra otros modelos de producción de vivienda por un equipo de investigación universitario (UDELAR-CSIC), externo a la federación cooperativa y al municipio.'),
  ('seed-48', 'SEED — Ingreso básico garantizado municipal', 'Stockton', 'Estados Unidos', 'inclusion', '2019', '125 residentes elegidos al azar en barrios de bajos ingresos recibieron 500 dólares mensuales sin condiciones durante dos años, financiado por filantropía y no por presupuesto municipal, impulsado por el entonces intendente Michael Tubbs.', 'Quienes recibieron el ingreso consiguieron empleo de tiempo completo al doble de la tasa del grupo de control y reportaron menos ansiedad y depresión; los propios investigadores aclaran que durante el segundo año, en plena pandemia, los resultados fueron menos concluyentes y la muestra era pequeña.', 'Universidad de Pensilvania (Center for Guaranteed Income Research)', 'https://www.stocktondemonstration.org/press-landing/guaranteed-income-increases-employment-improves-financial-and-physical-health', 'alta', 'Ensayo aleatorizado con grupo de control, diseñado y evaluado por investigadores universitarios independientes del municipio, con financiamiento de una fundación externa (Robert Wood Johnson Foundation).'),
  ('seed-49', 'Manzanas del Cuidado (Sistema Distrital de Cuidado)', 'Bogotá', 'Colombia', 'bienestar', '2020', 'Primera red de América Latina de centros barriales gratuitos para mujeres cuidadoras: mientras alguien más cuida de sus hijos o familiares dependientes, ellas acceden a formación, terminan el colegio, hacen ejercicio o buscan trabajo.', 'Superó 4,5 millones de atenciones y llegó a más de 750.000 personas y sus familias en cuatro años; ganó el Premio Internacional de Innovación Urbana de Guangzhou (2023) y un estudio cualitativo con entrevistas a usuarias documentó mejoras percibidas en su bienestar.', 'Alcaldía de Bogotá / Secretaría Distrital de la Mujer', 'https://bogota.gov.co/mi-ciudad/mujer/sistema-distrital-de-cuidado-transforma-vidas-de-mujeres-en-bogota', 'media', 'Las cifras de cobertura son oficiales del propio Distrito; existe un estudio cualitativo externo basado en entrevistas, pero no una evaluación de impacto cuantitativa e independiente.'),
  ('seed-50', 'Decidim — plataforma digital de participación ciudadana', 'Barcelona', 'España', 'gobierno', '2016', 'Plataforma pública y de código abierto donde cualquier vecino puede debatir, proponer y votar sobre el plan de gobierno de la ciudad; al ser de código abierto, cualquier otro municipio puede copiarla y adaptarla gratis.', 'El primer proceso participativo recibió más de 10.000 propuestas y un 71% terminó incluido en el plan municipal; hoy la tecnología la usan más de 400 instituciones en 20 países (México, Helsinki, Nueva York, la Asamblea Nacional francesa) y la Comisión Europea la reconoció en 2019 como uno de los proyectos de código abierto más innovadores de Europa.', 'Ajuntament de Barcelona', 'https://ajuntament.barcelona.cat/innovaciodemocratica/es/decidim', 'media', 'Las cifras de uso y adopción son difundidas por el propio Ayuntamiento y la comunidad del proyecto; el reconocimiento de la Comisión Europea premia la innovación de la herramienta, no mide su impacto en la calidad de las decisiones públicas.');
